function Read-Utf8([string]$Path) { [System.IO.File]::ReadAllText((Resolve-Path -LiteralPath $Path), (New-Object System.Text.UTF8Encoding($false))) }
function Write-Utf8([string]$Path,[string]$Text) { [System.IO.File]::WriteAllText((Resolve-Path -LiteralPath (Split-Path -Parent $Path)).Path + '\' + (Split-Path -Leaf $Path), $Text, (New-Object System.Text.UTF8Encoding($false))) }
function Replace-Exact([string]$Path,[string]$Old,[string]$New,[string]$Name) {
    $p=(Resolve-Path -LiteralPath $Path).Path; $t=[System.IO.File]::ReadAllText($p,(New-Object System.Text.UTF8Encoding($false)))
    $count=([regex]::Matches($t,[regex]::Escape($Old))).Count
    if($count -ne 1){ throw "$Name failed: expected exactly 1 match in $Path, found $count" }
    [System.IO.File]::WriteAllText($p,$t.Replace($Old,$New),(New-Object System.Text.UTF8Encoding($false)))
}
function Replace-Regex([string]$Path,[string]$Pattern,[string]$New,[string]$Name) {
    $p=(Resolve-Path -LiteralPath $Path).Path; $t=[System.IO.File]::ReadAllText($p,(New-Object System.Text.UTF8Encoding($false)))
    $count=([regex]::Matches($t,$Pattern,[Text.RegularExpressions.RegexOptions]::Singleline)).Count
    if($count -ne 1){ throw "$Name failed: expected exactly 1 regex match in $Path, found $count" }
    $t=[regex]::Replace($t,$Pattern,$New,[Text.RegularExpressions.RegexOptions]::Singleline)
    [System.IO.File]::WriteAllText($p,$t,(New-Object System.Text.UTF8Encoding($false)))
}
function Add-File([string]$Path,[string]$Content) {
    $dir=Split-Path -Parent $Path; if(-not(Test-Path $dir)){New-Item -ItemType Directory -Path $dir -Force | Out-Null}
    [System.IO.File]::WriteAllText((Join-Path (Resolve-Path $dir) (Split-Path -Leaf $Path)),$Content,(New-Object System.Text.UTF8Encoding($false)))
}
function Pass([string]$m){$script:results += "[PASS] $m"; Write-Host "[PASS] $m" -ForegroundColor Green}
function Fail([string]$m){$script:results += "[FAIL] $m"; Write-Host "[FAIL] $m" -ForegroundColor Red; throw $m}
function Repair-Mojibake([string]$Path) {
    if (-not (Test-Path $Path)) { return }
