package com.rationportal.service;

import com.rationportal.model.RationCard;
import com.rationportal.repository.RationCardRepository;
import org.springframework.lang.NonNull;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;

@Service
public class RationCardService {
    private final RationCardRepository repository;
    public RationCardService(RationCardRepository repository) { this.repository = repository; }
    public List<RationCard> getAll() { return repository.findAll(); }
    public List<RationCard> getPending() { return repository.findByStatusIgnoreCase("PENDING"); }
    public RationCard getByNumber(String number) {
        if (number == null || number.isBlank()) return null;
        return repository.findByRationCardNumber(number.trim()).orElse(null);
    }
    public List<RationCard> getApprovedCardsForOwner(String ownerEmail) {
        if (ownerEmail == null || ownerEmail.isBlank()) return List.of();
        List<RationCard> cards = repository.findByOwnerEmailIgnoreCase(ownerEmail.trim());
        List<RationCard> approved = new ArrayList<>();
        for (RationCard card : cards) {
            if (isApproved(card)) approved.add(card);
        }
        return approved;
    }
    public RationCard getApprovedCardForOwner(String ownerEmail) {
        List<RationCard> cards = getApprovedCardsForOwner(ownerEmail);
        return cards.isEmpty() ? null : cards.get(0);
    }
    public RationCard getApprovedCardForOwner(String rationCardNumber, String ownerEmail) {
        if (rationCardNumber == null || rationCardNumber.isBlank() || ownerEmail == null || ownerEmail.isBlank()) return null;
        RationCard card = repository.findByRationCardNumberAndOwnerEmailIgnoreCase(rationCardNumber.trim(), ownerEmail.trim()).orElse(null);
        return isApproved(card) ? card : null;
    }
    public boolean isApproved(RationCard card) {
        if (card == null || card.getStatus() == null) return false;
        String status = card.getStatus().trim().toUpperCase(Locale.ROOT);
        return "APPROVED".equals(status) || "ACTIVE".equals(status);
    }
    public RationCard save(@NonNull RationCard card) {
        String status = card.getStatus();
        if (status == null || status.isBlank()) status = "PENDING";
        status = status.trim().toUpperCase(Locale.ROOT);
        if (!Set.of("PENDING", "APPROVED", "ACTIVE", "REJECTED").contains(status)) status = "PENDING";
        card.setStatus(status);
        card.setApprovalStatus(status);
        if (card.getOwnerEmail() != null) card.setOwnerEmail(card.getOwnerEmail().trim().toLowerCase(Locale.ROOT));
        return repository.save(card);
    }
    public RationCard approve(String number) {
        RationCard card = getByNumber(number);
        if (card == null) return null;
        card.setStatus("APPROVED");
        card.setApprovalStatus("APPROVED");
        return repository.save(card);
    }
    public RationCard reject(String number) {
        RationCard card = getByNumber(number);
        if (card == null) return null;
        card.setStatus("REJECTED");
        card.setApprovalStatus("REJECTED");
        return repository.save(card);
    }
}
'@
Add-File (Join-Path $Root 'backend\src\main\java\com\rationportal\controller\RationCardApplicationController.java') @'
package com.rationportal.controller;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.rationportal.model.RationCard;
import com.rationportal.model.RationCardApplication;
import com.rationportal.repository.RationCardApplicationRepository;
import com.rationportal.repository.RationCardRepository;
import com.rationportal.service.NotificationService;
import org.springframework.http.ResponseEntity;
import org.springframework.lang.NonNull;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

@RestController
@RequestMapping({
        "/api/applications/ration-card",
        "/api/applications"
})
public class RationCardApplicationController {

    private final RationCardApplicationRepository repository;
    private final RationCardRepository rationCardRepository;
    private final ObjectMapper objectMapper;
    private final NotificationService notificationService;

    private static final Set<String> ALLOWED_STATUSES = Set.of(
            "SUBMITTED",
            "PENDING",
            "VERIFIED",
            "APPROVED",
            "REJECTED"
    );

    public RationCardApplicationController(
            RationCardApplicationRepository repository,
            RationCardRepository rationCardRepository,
            ObjectMapper objectMapper,
            NotificationService notificationService) {

        this.repository = repository;
        this.rationCardRepository = rationCardRepository;
        this.objectMapper = objectMapper;
        this.notificationService = notificationService;
    }

    @PostMapping
    public ResponseEntity<?> submitApplication(
            @RequestBody @NonNull Map<String, Object> request,
            Authentication authentication) {

        if (!isAuthenticated(authentication)) {
            return ResponseEntity.status(401)
                    .body(Map.of(
                            "message",
                            "Authentication required."
                    ));
        }

        try {
            String headOfFamily = getString(request, "headOfFamily");
            String mobile = getString(request, "mobile");
            String email = authentication.getName();
            String cardType = getString(request, "cardType");
            String address = getString(request, "address");
            String district = getString(request, "district");
            String state = getString(request, "state");
            String pincode = getString(request, "pincode");

            Object familyMembersObject = request.get("familyMembers");

            if (headOfFamily.isBlank()
                    || mobile.isBlank()
                    || email.isBlank()
                    || cardType.isBlank()
                    || address.isBlank()
                    || district.isBlank()
                    || state.isBlank()
                    || pincode.isBlank()
                    || familyMembersObject == null) {

                return ResponseEntity.badRequest()
                        .body(Map.of(
                                "message",
                                "All required application details must be provided."
                        ));
            }

            if (!(familyMembersObject instanceof List<?> familyMembers)) {

                return ResponseEntity.badRequest()
                        .body(Map.of(
                                "message",
                                "Family members data must be a valid list."
                        ));
            }

            if (familyMembers.isEmpty()) {

                return ResponseEntity.badRequest()
                        .body(Map.of(
                                "message",
                                "At least one family member is required."
                        ));
            }

            RationCardApplication application =
                    new RationCardApplication();

            application.setApplicationNumber(
                    "RCAPP-" + UUID.randomUUID()
                            .toString()
                            .replace("-", "")
                            .substring(0, 12)
                            .toUpperCase()
            );

            application.setApplicantName(headOfFamily);
            application.setMobile(mobile);
            application.setEmail(email);
            application.setCardType(cardType);
            application.setFamilyMembers(familyMembers.size());

            application.setFamilyMembersData(
                    objectMapper.writeValueAsString(familyMembers)
            );

            application.setAddress(address);
            application.setDistrict(district);
            application.setState(state);
            application.setPincode(pincode);
            application.setStatus("SUBMITTED");

            RationCardApplication savedApplication =
                    repository.save(application);

            try {
                notificationService.sendApplicationSubmittedEmail(
                        savedApplication.getEmail(),
                        savedApplication.getApplicantName(),
                        savedApplication.getApplicationNumber()
                );
            } catch (Exception notificationException) {
                System.err.println(
                        "APPLICATION SUBMITTED EMAIL NOTIFICATION FAILED: "
                                + notificationException.getMessage()
                );
            }

            try {
                notificationService.sendApplicationSubmittedSms(
                        savedApplication.getMobile(),
                        savedApplication.getApplicationNumber()
                );
            } catch (Exception notificationException) {
                System.err.println(
                        "APPLICATION SUBMITTED SMS NOTIFICATION FAILED: "
                                + notificationException.getMessage()
                );
            }

            return ResponseEntity.ok(savedApplication);

        } catch (JsonProcessingException e) {

            return ResponseEntity.badRequest()
                    .body(Map.of(
                            "message",
                            "Unable to process family member information."
                    ));

        } catch (Exception e) {

            return ResponseEntity.internalServerError()
                    .body(Map.of(
                            "message",
                            "Unable to submit the ration card application."
                    ));
        }
    }

    @GetMapping
    public ResponseEntity<?> getApplications(
            Authentication authentication) {

        if (!isAuthenticated(authentication)) {
            return ResponseEntity.status(401)
                    .body(Map.of(
                            "message",
                            "Authentication required."
                    ));
        }

        boolean isAdmin = isAdmin(authentication);

        List<RationCardApplication> applications;

        if (isAdmin) {
            applications = repository.findAll();
        } else {
            applications =
                    repository.findAllByEmailOrderByCreatedAtDesc(
                            authentication.getName()
                    );
        }

        return ResponseEntity.ok(applications);
    }

    @GetMapping("/{applicationNumber}")
    public ResponseEntity<?> getApplicationByNumber(
            @PathVariable @NonNull String applicationNumber,
            Authentication authentication) {

        if (!isAuthenticated(authentication)) {
            return ResponseEntity.status(401)
                    .body(Map.of(
                            "message",
                            "Authentication required."
                    ));
        }

        RationCardApplication application =
                repository.findByApplicationNumber(applicationNumber)
                        .orElse(null);

        if (application == null) {
            return ResponseEntity.status(404)
                    .body(Map.of(
                            "message",
                            "Application not found."
                    ));
        }

        boolean isAdmin = isAdmin(authentication);

        if (!isAdmin
                && !authentication.getName()
                .equalsIgnoreCase(application.getEmail())) {

            return ResponseEntity.status(404)
                    .body(Map.of(
                            "message",
                            "Application not found."
                    ));
        }

        return ResponseEntity.ok(application);
    }

    @PutMapping("/{applicationNumber}/status")
    public ResponseEntity<?> updateApplicationStatus(
            @PathVariable @NonNull String applicationNumber,
            @RequestBody @NonNull Map<String, Object> request,
            Authentication authentication) {

        if (!isAuthenticated(authentication)) {
            return ResponseEntity.status(401)
                    .body(Map.of(
                            "message",
                            "Authentication required."
                    ));
        }

        if (!isAdmin(authentication)) {

            return ResponseEntity.status(403)
                    .body(Map.of(
                            "message",
                            "Only administrators can update application status."
                    ));
        }

        String requestedStatus = getString(request, "status");

        if (requestedStatus.isBlank()) {

            return ResponseEntity.badRequest()
                    .body(Map.of(
                            "message",
                            "Application status is required."
                    ));
        }

        String normalizedStatus =
                requestedStatus.trim().toUpperCase();

        if (!ALLOWED_STATUSES.contains(normalizedStatus)) {

            return ResponseEntity.badRequest()
                    .body(Map.of(
                            "message",
                            "Invalid application status.",
                            "allowedStatuses",
                            ALLOWED_STATUSES
                    ));
        }

        RationCardApplication application =
                repository.findByApplicationNumber(applicationNumber)
                        .orElse(null);

        if (application == null) {

            return ResponseEntity.status(404)
                    .body(Map.of(
                            "message",
                            "Application not found."
                    ));
        }

        String previousStatus = application.getStatus();

        application.setStatus(normalizedStatus);

        RationCardApplication savedApplication =
                repository.save(application);

        syncRationCardForApplication(savedApplication);

        try {
            notificationService.sendApplicationStatusEmail(
                    savedApplication.getEmail(),
                    savedApplication.getApplicantName(),
                    savedApplication.getApplicationNumber(),
                    savedApplication.getStatus()
            );
        } catch (Exception notificationException) {
            System.err.println(
                    "APPLICATION STATUS EMAIL NOTIFICATION FAILED: "
                            + notificationException.getMessage()
            );
        }

        try {
            notificationService.sendApplicationStatusSms(
                    savedApplication.getMobile(),
                    savedApplication.getApplicationNumber(),
                    savedApplication.getStatus()
            );
        } catch (Exception notificationException) {
            System.err.println(
                    "APPLICATION STATUS SMS NOTIFICATION FAILED: "
                            + notificationException.getMessage()
            );
        }

        return ResponseEntity.ok(
                Map.of(
                        "message",
                        "Application status updated successfully.",
                        "applicationNumber",
                        savedApplication.getApplicationNumber(),
                        "previousStatus",
                        previousStatus == null ? "" : previousStatus,
                        "status",
                        savedApplication.getStatus(),
                        "emailNotification",
                        "ATTEMPTED",
                        "smsNotification",
                        "ATTEMPTED",
                        "application",
                        savedApplication
                )
        );
    }

    private boolean isAuthenticated(Authentication authentication) {

        return authentication != null
                && authentication.isAuthenticated()
                && authentication.getName() != null
                && !authentication.getName().isBlank();
    }

    private boolean isAdmin(Authentication authentication) {

        if (!isAuthenticated(authentication)) {
            return false;
        }

        for (var authority : authentication.getAuthorities()) {
            if ("ROLE_ADMIN".equals(authority.getAuthority())) return true;
        }
        return false;
    }

    private String getString(
            Map<String, Object> request,
            String fieldName) {

        Object value = request.get(fieldName);

        if (value == null) {
            return "";
        }

        return value.toString().trim();
    }
    private void syncRationCardForApplication(
            RationCardApplication application) {

        String ownerEmail = application.getEmail() == null
                ? ""
                : application.getEmail().trim().toLowerCase();

        if (ownerEmail.isBlank()) {
            return;
        }

        String cardNumber = "RC-" + application.getApplicationNumber();

        RationCard card = rationCardRepository
                .findByRationCardNumber(cardNumber)
                .orElseGet(RationCard::new);

        card.setRationCardNumber(cardNumber);
        card.setCardType(application.getCardType());
        card.setHeadOfFamily(application.getApplicantName());
        card.setAddress(application.getAddress());
        card.setDistrict(application.getDistrict());
        card.setState(application.getState());
        card.setOwnerEmail(ownerEmail);

        String applicationStatus = application.getStatus() == null
                ? "PENDING"
                : application.getStatus().trim().toUpperCase();

        if ("APPROVED".equals(applicationStatus)) {
            card.setStatus("APPROVED");
            card.setApprovalStatus("APPROVED");
        } else if ("REJECTED".equals(applicationStatus)) {
            card.setStatus("REJECTED");
            card.setApprovalStatus("REJECTED");
        } else {
            card.setStatus("PENDING");
            card.setApprovalStatus("PENDING");
        }

        rationCardRepository.save(card);
    }

}
