<script>
(function(){
"use strict";
function setText(id,value){var el=document.getElementById(id);if(el)el.textContent=value;}
async function loadLiveDashboard(){
    if(!window.rationAuth || typeof window.rationAuth.authenticatedFetch!=="function") return;
    try{
        var response=await window.rationAuth.authenticatedFetch("https://ration-portal-backend.onrender.com/api/dashboard/metrics");
        if(!response.ok) throw new Error("Dashboard API returned "+response.status);
        var data=await response.json();
        var card=data.rationCard||{};
        setText("dashboardCardStatus", card.status||"NOT ISSUED");
        setText("dashboardRiceQuota", ((data.familyRiceQuotaKg==null?0:data.familyRiceQuotaKg))+" kg");
        setText("dashboardFamilyCount", data.familyMembers==null?0:data.familyMembers);
        setText("dashboardAdultCount", data.adultCount==null?0:data.adultCount);
        setText("dashboardChildCount", data.childCount==null?0:data.childCount);
        setText("dashboardFamilyRiceQuota", ((data.familyRiceQuotaKg==null?0:data.familyRiceQuotaKg))+" kg");
        setText("dashboardApplicationStatus", data.applicationStatus||"NONE");
        var rows=document.querySelectorAll(".distribution-table tbody tr");
        var records=Array.isArray(data.recentDistribution)?data.recentDistribution:[];
        if(rows.length){
            var tbody=rows[0].parentElement;
            tbody.innerHTML="";
            if(!records.length){tbody.innerHTML='<tr><td colspan="4">No distribution records available for your approved ration card.</td></tr>';}
            else records.forEach(function(r){var tr=document.createElement("tr");[r.date||"--",r.fpsId||"--",(r.quantityKg==null?"--":r.quantityKg+" kg"),r.status||"--"].forEach(function(v){var td=document.createElement("td");td.textContent=v;tr.appendChild(td);});tbody.appendChild(tr);});
        }
    }catch(e){console.error("Live dashboard load failed",e);}
}
document.addEventListener("DOMContentLoaded",loadLiveDashboard);
})();
</script>
