# 4. Static Stage 10-30 verification
$security=Read-Utf8 (Join-Path $Root 'backend\src\main\java\com\rationportal\config\SecurityConfig.java')
$auth=Read-Utf8 (Join-Path $Root 'backend\src\main\java\com\rationportal\controller\AuthController.java')
