if($security -match 'STATELESS' -and $security -match 'addFilterBefore' -and $security -match 'anyRequest\(\)\.authenticated' -and $security -match 'hasRole\("ADMIN"\)'){Pass 'Stage 10 security foundation'}else{Fail 'Stage 10 security foundation check failed'}
