if($auth -match 'setRole\("CITIZEN"\)' -and $auth -match 'termsAccepted' -and $auth -match 'reset-password'){Pass 'Stage 12/14 registration and reset server enforcement checks'}else{Fail 'Stage 12/14 server enforcement check failed'}
if($rc -match '@PutMapping\("/admin/\{number\}/approve"\)' -and $rc -match '@PutMapping\("/admin/\{number\}/reject"\)' -and $rc -match 'authentication\.getName\(\)'){Pass 'Stage 15/17/25 ration-card ownership and approval endpoints'}else{Fail 'Stage 15/17/25 ration-card workflow check failed'}
if($app -match 'syncRationCardForApplication' -and $app -match 'RationCardRepository' -and $app -match 'APPROVED' -and $app -match 'REJECTED'){Pass 'Stage 25 application-to-ration-card approval workflow check'}else{Fail 'Stage 25 workflow synchronization check failed'}
if($handler -match '@RestControllerAdvice' -and $handler -match 'Malformed request body' -and $handler -match 'unexpected server error'){Pass 'Stage 26 safe error handling check'}else{Fail 'Stage 26 exception-handling check failed'}

# Stages 19-24: server-side ownership/role/service authorization coverage.
$family=Read-Utf8 (Join-Path $Root 'backend\src\main\java\com\rationportal\controller\FamilyMemberController.java')
$distribution=Read-Utf8 (Join-Path $Root 'backend\src\main\java\com\rationportal\controller\DistributionLogController.java')
$onorc=Read-Utf8 (Join-Path $Root 'backend\src\main\java\com\rationportal\service\OnorcPortabilityService.java')
$transparency=Read-Utf8 (Join-Path $Root 'backend\src\main\java\com\rationportal\controller\TransparencyController.java')
if($family -match 'getOwnerEmail' -and ($family -match 'isApproved' -or ($family -match 'APPROVED' -and $family -match 'ACTIVE' -and $family -match 'ownerEmail'))){Pass 'Stage 19 family ownership and approval gate'}else{Fail 'Stage 19 family ownership check failed'}
if($distribution -match 'Only ADMIN can create distribution records' -and $distribution -match 'getOwnerEmail' -and ($distribution -match 'isApproved' -or ($distribution -match 'APPROVED' -and $distribution -match 'ACTIVE'))){Pass 'Stage 20 distribution ownership/admin mutation gate'}else{Fail 'Stage 20 distribution security check failed'}
if($guard -match 'applications.html' -and $app -match 'isAdmin' -and $app -match 'findAllByEmailOrderByCreatedAtDesc'){Pass 'Stage 21 citizen applications are authenticated and owner-scoped'}else{Fail 'Stage 21 application authorization check failed'}
if($handler -match 'FORBIDDEN' -and (Read-Utf8 (Join-Path $Root 'backend\src\main\java\com\rationportal\controller\GrievanceController.java')) -match 'rationCardRepository'){Pass 'Stage 22 grievance ownership/security'}else{Fail 'Stage 22 grievance security check failed'}
if($onorc -match 'findByRationCardNumberAndOwnerEmailIgnoreCase' -and $onorc -match 'isApproved'){Pass 'Stage 23 ONORC ownership and approval gate'}else{Fail 'Stage 23 ONORC security check failed'}
if($transparency -match 'isAuthenticated' -and $transparency -match 'totalRationCards' -and $transparency -notmatch 'result\.put\(\"(email|mobile|address|ownerEmail|familyMembersData)\"'){Pass 'Stage 24 transparency authorization and aggregate-only data check'}else{Fail 'Stage 24 transparency check failed'}

# Stage 12 frontend terms enforcement.
$register=Read-Utf8 (Join-Path $Root 'frontend\pages\register.html')
$reset=Read-Utf8 (Join-Path $Root 'frontend\pages\reset-password.html')
$config=Read-Utf8 (Join-Path $Root 'frontend\config.js')
if($register -match 'termsAccepted' -and $register -match 'required' -and $reset -match 'config.js' -and $config -match 'reset-password.html'){Pass 'Stage 12 frontend terms enforcement'}else{Fail 'Stage 12 frontend terms check failed'}

# Stage 13: every active HTML password field must have a nearby toggle/button marker.
$htmls=Get-ChildItem (Join-Path $Root 'frontend\pages') -Filter *.html -File
$pwMissing=@()
foreach($h in $htmls){$s=Get-Content $h.FullName -Raw;if($s -match 'type=["'']password'){if($s -notmatch 'togglePassword|password-toggle|data-password-toggle|showPassword|newPasswordToggle|confirmPasswordToggle'){$pwMissing += $h.Name}}}
if($pwMissing.Count -eq 0){Pass 'Stage 13 password-field toggle coverage'}else{Fail ('Stage 13 password toggle missing on: '+($pwMissing -join ', '))}

# Stage 27: detect actual broken local HTML links after path normalization.
$broken=@(); foreach($h in $htmls){$base=Split-Path $h.FullName -Parent; $s=Get-Content $h.FullName -Raw; foreach($m in [regex]::Matches($s,'href=["'']([^"''#?]+)')){$href=$m.Groups[1].Value;if($href -match '^(https?:|mailto:|tel:|javascript:|#|/)'){continue};$target=[IO.Path]::GetFullPath((Join-Path $base $href));if($href -match '\.html$' -and -not(Test-Path $target)){$broken += "$($h.Name) -> $href"}}}
if($broken.Count -eq 0){Pass 'Stage 27 local HTML navigation link check'}else{Fail ('Stage 27 broken links: '+($broken -join '; '))}

# Stage 27 fake/demo text audit: active source must not contain known placeholders.
$active=@(Get-ChildItem (Join-Path $Root 'frontend') -Recurse -File -Include *.html,*.js | Where-Object {$_.FullName -notmatch '\\(backup|backups|frontend-final-backup)'})
$fake=@(); foreach($h in $active){$s=Get-Content $h.FullName -Raw;if($s -match 'Backend integration pending|Illustrative portal statistics|XXXX-[0-9]|DEMO ACCOUNT DISPLAY'){$fake += $h.FullName.Substring($Root.Length+1)}}
if($fake.Count -eq 0){Pass 'Stage 18/27 no known fake/demo placeholder audit'}else{Fail ('Known fake/demo placeholders remain: '+($fake -join '; '))}

# Stage 29 build and formatting.
Set-Location (Join-Path $Root 'backend')
& .\gradlew.bat clean build
if($LASTEXITCODE -ne 0){Fail 'Stage 29 Gradle clean build failed'}else{Pass 'Stage 29 Gradle clean build'}
Set-Location $Root
& git diff --check
if($LASTEXITCODE -ne 0){Fail 'Stage 29 git diff --check failed'}else{Pass 'Stage 29 git diff --check'}

# Secret scan: fail only on likely literal credentials, not property placeholders.
$tracked=@(& git ls-files); $secretHits=@(); foreach($f in $tracked){if($f -match '(^|/)(build|bin|\.gradle)/'){continue};$full=Join-Path $Root ($f -replace '/','\');if(Test-Path $full){$s=Get-Content $full -Raw -ErrorAction SilentlyContinue;if($s -match '(?i)(brevo|api[_-]?key|jwt[_-]?secret|password)\s*[:=]\s*["''][A-Za-z0-9_\-]{20,}["'']'){$secretHits += $f}}}
if($secretHits.Count -eq 0){Pass 'Stage 29 tracked-source secret scan'}else{Fail ('Potential hardcoded secret found: '+($secretHits -join ', '))}

# Stage 28/30 cannot be truthfully marked production PASS without live credentials and real workflow evidence.
$results += '[BLOCKED-EVIDENCE] Stage 28/30 live production matrix and end-to-end approval workflow require actual deployed endpoint responses and test accounts; this script will not fabricate PASS.'
$results += '[BLOCKED-EVIDENCE] Stage 29 Render deployment/push is not performed automatically. Review diff, commit, push, then verify Render with real HTTP responses.'

} catch {
    $message = $_.Exception.Message
    $script:results += "[FAIL-STOP] $message"
    $script:results | Set-Content -LiteralPath $report -Encoding UTF8
    Write-Host "`n========== STAGE 10-30 MASTER RESULT: STOPPED ==========" -ForegroundColor Red
    $script:results | ForEach-Object { Write-Host $_ }
    Write-Host "BACKUP: $backup" -ForegroundColor Yellow
    Write-Host "REPORT: $report" -ForegroundColor Yellow
    Write-Host "NO GIT COMMIT/PUSH WAS PERFORMED." -ForegroundColor Cyan
    exit 1
}

# Report
$results | Set-Content -LiteralPath $report -Encoding UTF8
Write-Host "`n========== STAGE 10-30 MASTER RESULT ==========" -ForegroundColor Cyan
$results | ForEach-Object {Write-Host $_}
Write-Host "`nBACKUP: $backup" -ForegroundColor Yellow
Write-Host "REPORT: $report" -ForegroundColor Yellow
Write-Host "MASTER OPERATION STOPPED AFTER VERIFIED LOCAL CHECKS. NO GIT COMMIT/PUSH WAS PERFORMED." -ForegroundColor Cyan